package com.tripnest.service; import com.tripnest.dto.ApiDtos.*; import com.tripnest.entity.*; import com.tripnest.exception.ApiException; import com.tripnest.repository.UserRepository; import com.tripnest.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; @Service public class AuthService {final UserRepository repo;final PasswordEncoder enc;final JwtService jwt; public AuthService(UserRepository r,PasswordEncoder e,JwtService j){repo=r;enc=e;jwt=j;} public Auth register(Register x){if(repo.existsByEmail(x.email().toLowerCase()))throw new ApiException(HttpStatus.CONFLICT,"An account with that email already exists.");User u=new User();u.setFullName(x.fullName().trim());u.setEmail(x.email().toLowerCase().trim());u.setPasswordHash(enc.encode(x.password()));User saved=repo.save(u);return new Auth(jwt.issue(saved.getEmail(),saved.getRole().name()),new UserView(saved.getId(),saved.getFullName(),saved.getEmail(),saved.getRole().name()));} public Auth login(Login x){User u=repo.findByEmail(x.email().toLowerCase()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password."));if(!enc.matches(x.password(),u.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password.");return new Auth(jwt.issue(u.getEmail(),u.getRole().name()),new UserView(u.getId(),u.getFullName(),u.getEmail(),u.getRole().name()));} }
